"""One registration per canonical Skyrim flow."""
from .scenarios import combat, crime, followers, menus, rewards, specs, v1
from .scenarios import (
    ai,
    combat,
    dialogue,
    input,
    interface,
    inventory,
    join,
    magic,
    mounts,
    movement,
    objects,
    physics,
    session,
    story,
    travel,
    world,
)

def register_flows(registry):
    registry.add('session-roster', ['session'], lambda ctx: session.scenario_session_roster(ctx), doc='Everyone connected is in the session (there are no parties): each game lists the other\n    player, and both agree the host hosts.')
    registry.add('party-panel', ['reload', 'session', 'ui'], lambda ctx: session.scenario_party_panel(ctx), doc='The party panel (the in-game UI) lists the other player in each game, with its health, and\n    still does after both games hot reload.')
    registry.add('party-shows-levels', ['session', 'ui'], lambda ctx: session.scenario_party_shows_levels(ctx), doc="Each party panel shows the other player's level, and a level-up in either game (the console's\n    advlevel, as a level-up raises it) reaches the other's panel. The baseline puts the levels back.")
    registry.add('late-join-client', ['hands', 'inventory', 'session', 'spawn', 'values'], lambda ctx: session.scenario_late_join_client(ctx), doc="The client leaves and joins again while the host's world changed: it must see the world as it\n    is now (the host's player and NPC as they are), and the host must drop the client's character\n    while it is away.")
    registry.add('host-rejoins', ['session', 'spawn'], lambda ctx: session.scenario_host_rejoins(ctx), doc='The host leaves (which ends the session for everyone: the host is the session) and hosts\n    again: the client lost its host, its join panel says it reconnects, and it does by itself\n    (JoinService). The host must own the NPCs it spawns, not the client.')
    registry.add('host-kicks-client', ['session', 'spawn'], lambda ctx: session.scenario_host_kicks_client(ctx), doc="The host removes the client from the session: the client is disconnected, its character\n    leaves the host's game and the host no longer lists it. The client can join again.")
    registry.add('join-refused-shows-why', ['session'], lambda ctx: session.scenario_join_refused_shows_why(ctx), doc="A refused game's join status says why (a reason code and a sentence), and the host's chat says\n    who could not join. The client asks stand-in hosts (coop_peer) on another build, on another\n    Skyrim and SKSE, and a full one; games on another build and on another Skyrim ask the real host.\n    The client then joins the host again.")
    registry.add('join-panel-shows-refusal', ['join', 'session', 'ui'], lambda ctx: session.scenario_join_panel_shows_refusal(ctx), doc="A friend's game at the main menu is refused (a full session): the join panel shows why, Copy puts the\n    reason and the sentence on the clipboard, and Back puts the panel away while the main menu takes none of the\n    clicks (UiService, UiInput). The client's game then starts again as the duo's.")
    registry.add('join-refused-plugins-differ', ['restart', 'session'], lambda ctx: session.scenario_join_refused_plugins_differ(ctx), doc="Two real games with different load orders: the client game restarts with one plugin more\n    than the host, asks the host to join and is refused with that difference listed; the host's chat\n    says why. The client then restarts with the host's load order and joins again.")
    registry.add('difficulty-follows-host', ['session'], lambda ctx: session.scenario_difficulty_follows_host(ctx), doc="The session's difficulty is the host's: a joining game takes it, follows the host's changes\n    and cannot change away from it; the host's own is never changed; leaving gives the client's game\n    its own difficulty back.")
    registry.add('global-reaches-guest', ['world'], lambda ctx: story.scenario_global_reaches_guest(ctx), doc="A global the host's game changes (the console's `set`, as a fragment's SetValue does) takes the\n    host's value on the client; the client's own change does not reach the host.")
    registry.add('late-join-gets-globals', ['session', 'world'], lambda ctx: story.scenario_late_join_gets_globals(ctx), doc="A client that joins after the host changed a global starts with the host's value.")
    registry.add('quest-stage-reaches-guest', ['quest', 'world'], lambda ctx: story.scenario_quest_stage_reaches_guest(ctx), doc="A stage the host's game sets is done on the client too, with its objective, through the client's\n    own SetStage; the stage's fragment (a world script) runs on the host only.")
    registry.add('guest-story-starts-no-quest', ['cells', 'quest', 'world'], lambda ctx: story.scenario_guest_story_starts_no_quest(ctx), doc="Both players walk into the Bannered Mare: each game raises its own arrival story event (a location\n    change). The host's story manager starts quests for it (the bard's song, the hold's radiant quests); the\n    client's decides nothing, its event handled with no quest started: quests come from the host.")
    registry.add('guest-location-change-starts-story', ['cells', 'quest', 'story', 'world'], lambda ctx: story.scenario_guest_location_change_starts_story(ctx), doc="The client leads the party into the Bannered Mare (party-model.md rule 4). Its own game's story manager starts\n    nothing; it sends its arrival (CLOC) to the host, whose game raises it for the client's character and judges it\n    for that character. The party arrives once: of the two arrivals the host's story manager sees, the copy's and its\n    own player's, the first it processes starts the arrival's quests (a node passes), the second starts none (the bard's\n    song and the greeting start once).")
    registry.add('guest-craft-raises-story', ['menus', 'quest', 'story', 'world'], lambda ctx: story.scenario_guest_craft_raises_story(ctx), doc="The client cooks beef at QASmoke's cooking spit: E opens its menu, E takes the recipe list, Up or Down to the one\n    recipe its salt and beef make, E and the box's Yes cook it. Its own game's story manager starts nothing for the\n    craft (CRFT); it sends the craft to the host, whose game raises it for the client's character and processes it.")
    registry.add('guest-spawns-no-critters', ['objects', 'scripts', 'world'], lambda ctx: story.scenario_guest_spawns_no_critters(ctx), doc="The host places a critter spawner: its script (CritterSpawn, on loading) places the dragonflies on the\n    host's game, and the client shows those. The client's own spawner (made as the host's created object) runs\n    no world script, so it places none of its own.")
    registry.add('wildlife-takes-hosts-pick', ['cells', 'spawn'], lambda ctx: story.scenario_wildlife_takes_hosts_pick(ctx), doc="Riverwood's placed leveled wildlife (a Rabbit reference can roll a Fox) rolls on each game: the client's\n    copy takes the host's pick (its base swapped, CharacterService::ApplyPlacedBase) and stays enabled and loaded.")
    registry.add('guest-joins-by-invite', ['session', 'spawn', 'steam', 'two-accounts', 'ui'], lambda ctx: join.scenario_guest_joins_by_invite(ctx), doc='A friend joins the host\'s session from a Steam invite, no address or port (two accounts: docs/design/testing.md,\n    "Two Steam accounts"): the client leaves its direct session; the host\'s game makes a lobby and invites the\n    client\'s account; the client\'s player accepts (its Steam opens the invite\'s join link); its game joins the lobby,\n    connects to the host through Valve\'s network, and joins the session through that connection (enet tunnelled over\n    it). Each game shows the other player and the party panels list each other; leaving the Steam session\n    drops the client\'s character from the host\'s game. Ends joined directly again.')
    registry.add('loaded-save-hosts-then-joins-friend', ['session', 'steam', 'two-accounts', 'ui'], lambda ctx: join.scenario_loaded_save_hosts_then_joins_friend(ctx), doc="A player loads a save and is hosting on Steam by itself (TESLoadGameEvent; its chat says so); a friend's invite\n    then reaches it, and its game, hosting alone, steps down and joins the friend's session through Steam. Each chat\n    says who joined. Ends joined directly again.")
    registry.add('guest-cannot-save', ['save', 'session'], lambda ctx: join.scenario_guest_cannot_save(ctx), doc="A guest's game refuses every save while it is in the host's session (Save_Impl's hook, SaveService) and its chat\n    says why: the console's `save`, the quicksave key (F5) and the engine's autosave at a load door write nothing (the\n    autosave says so once a session). The host's game saves.")
    registry.add('guest-cannot-load', ['join', 'save', 'session'], lambda ctx: join.scenario_guest_cannot_load(ctx), doc="A guest's load does nothing and explains why in chat, even when a real save exists.")
    registry.add('host-loads-party', ['join', 'save', 'session'], lambda ctx: join.scenario_host_loads_party(ctx), doc="A chosen host load restores an older save on both games, with each player's own character and place.")
    registry.add('host-quickloads-party', ['join', 'save', 'session'], lambda ctx: join.scenario_host_quickloads_party(ctx), doc='The host presses quicksave then quickload: both games load it and rejoin as their saved characters.')
    registry.add('host-menu-loads-party', ['join', 'save', 'session'], lambda ctx: join.scenario_host_menu_loads_party(ctx), doc='The host selects a save from the System Load menu; both games load it and keep their saved characters.')
    registry.add('host-save-keeps-guest-character', ['join', 'save', 'session'], lambda ctx: join.scenario_host_save_keeps_guest_character(ctx), doc="The host's game keeps the guest's character from the guest's game: from its joining, and on its changes (gold\n    the guest picks up reaches the host's record within seconds); a save of the host's game writes it into the save's\n    SKSE co-save (SaveService, CoSave).")
    registry.add('guest-brings-character-into-hosts-world', ['join', 'save', 'session'], lambda ctx: join.scenario_guest_brings_character_into_hosts_world(ctx), doc="A friend new to the host's save joins from a game of its own (a direct connection): its game takes its\n    character (level 9, Armsman, Firebolt, an iron sword), receives the host's save and loads it, and plays that\n    character in the host's world, which the host's game then keeps (JoinService, HostSaveTransfer, JoinBridge).")
    registry.add('guest-joins-from-main-menu-as-kept-character', ['join', 'save', 'session', 'v1'], lambda ctx: join.scenario_guest_joins_from_main_menu_as_kept_character(ctx), doc="A friend the host's save knows joins from the main menu (its game just started, no save loaded): the host's\n    save comes, and its player is the character the host's game keeps (level and perks from its last session).")
    registry.add('guest-makes-character-then-joins', ['join', 'save', 'session'], lambda ctx: join.scenario_guest_makes_character_then_joins(ctx), doc="An unknown friend joins first, then creates and names Rinara and arrives automatically. The host's\n    copy matches her chosen appearance, spells and inventory; another invite uses the kept character.")
    registry.add('first-time-join-by-invite', ['join', 'save', 'session', 'steam', 'two-accounts'], lambda ctx: join.scenario_first_time_join_by_invite(ctx), doc=None)
    registry.add('first-time-join-breton', ['join', 'save', 'session'], lambda ctx: join.scenario_first_time_join_breton(ctx), doc=None)
    registry.add('guest-changes-looks-in-session', ['join', 'session', 'spawn'], lambda ctx: join.scenario_guest_changes_looks_in_session(ctx), doc="The client's player changes its looks while joined: in the race menu (showracemenu: a war paint, a nose, eyes,\n    hair, a new name), then by catching vampirism (its race switches to the Nord vampire's, by setrace as the disease's\n    script does). Each time the host's existing copy changes: its base saves the client's bytes and its head is painted\n    with the tints the client's head shows, a vampire's pale skin too (CharacterService::OnPlayerLooksChange,\n    HostCharacters::OnRespawn). The client's game then starts again as the duo's.")
    registry.add('death-stage-runs-once', ['quest', 'scripts', 'spawn', 'world'], lambda ctx: story.scenario_death_stage_runs_once(ctx), doc='The host kills an NPC whose script sets a quest stage on its death (Valdr: defaultSetStageOnDeath, which\n    then goes to its "inactive" state). The script runs on the host\'s game; the client\'s copy dies too, but its\n    script stays waiting: a stage it set would run the quest\'s fragment a second time.')
    registry.add('quest-completes-for-guest', ['quest', 'world'], lambda ctx: story.scenario_quest_completes_for_guest(ctx), doc="The host's game completes a quest: completed on the client, its objectives as the host's.")
    registry.add('quest-roles-match-host', ['quest', 'world'], lambda ctx: story.scenario_quest_roles_match_host(ctx), doc="A radiant quest the host's game starts runs on the client with the host's picks for its roles\n    (who gives the job), not rolled by the client, and the client runs none of its start's fragments.")
    registry.add('quest-fill-loads-on-guest', ['quest', 'world'], lambda ctx: story.scenario_quest_fill_loads_on_guest(ctx), doc="The host's quest fills a role with a reference in a cell neither game loaded (as a radiant quest fills its\n    target): the host's game reads it from the plugin, and so does the client's, the quest's role filled the same.")
    registry.add('late-join-gets-quests', ['quest', 'session', 'world'], lambda ctx: story.scenario_late_join_gets_quests(ctx), doc="A client that joins after the host's game moved a quest on starts with the host's quest, taken as a\n    load takes it: no fragment runs on the client.")
    registry.add('steady-state', ['movement', 'session', 'spawn'], lambda ctx: movement.scenario_steady_state(ctx), doc="Desync checker: every actor's full state matches between owner and copy.")
    registry.add('move-host-npc', ['movement'], lambda ctx: movement.scenario_move_host_npc(ctx), doc="Host moves its NPC to a player; the client's copy must end up where the host's NPC is.")
    registry.add('copy-jumps-with-owner', ['movement', 'spawn'], lambda ctx: movement.scenario_copy_jumps_with_owner(ctx), doc="The host puts its NPC 900 units away at once (the console's setpos, as a script's MoveTo does): the client's\n    copy jumps there too, never sliding across in between (Movement::Teleported).")
    registry.add('remove-host-npc', ['spawn'], lambda ctx: travel.scenario_remove_host_npc(ctx), doc="Host disables an NPC it owns; the client's copy must disappear.")
    registry.add('copy-ends-voice-line', ['ai', 'dialogue'], lambda ctx: dialogue.scenario_copy_ends_voice_line(ctx), doc="The host player talks to its NPC: she greets him, and the client's copy plays the same line\n    (NotifyDialogue) with the same subtitle (NotifySubtitle) and ends it, as the host's NPC does. SpeakSound only queues a line; the engine's\n    voice upkeep in Character::UpdateAI starts and ends it (Actor::UpdateSoundCallback,\n    Character::UpdateVoiceTimer), which copies run from HookUpdateAI. A copy holds a package, its owner's\n    (AiStateService) or the engine's do-nothing one (HookCheckForNewPackage): an actor without one gets no\n    UpdateAI once its 3D is far enough from the camera to fade (Character::ShouldOnlyCheckPackage).")
    registry.add('dialogue-peer-starts', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_peer_starts(ctx), doc="The client talks to its copy of the host's NPC: the host's player is the one talking (its game runs the\n    conversation with the real NPC, without its menu: the host plays on), and the client's menu opens on the copy\n    with the host's list: its topics, lines and texts, in its order (docs/design/shared-dialogue.md).")
    registry.add('dialogue-last-one-out-ends-it', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_last_one_out_ends_it(ctx), doc="A player leaving (Tab) leaves the conversation on for the others; the last one out ends it. The host talks\n    and the client joins by talking to its copy; the client leaves, the host's stays, and the host's Tab ends it.\n    Then the other way round: the host leaves first and its conversation goes on without its menu, until the\n    client leaves too.")
    registry.add('dialogue-nobody-moves', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_nobody_moves(ctx), doc="The client talks to its copy while the host stands 1500 units off: the host's player is the one talking\n    (its game runs the conversation from where it stands, without its menu), and neither player is moved for it.\n    The client's menu lists the options and stays open; its Tab, the last one out, ends it.")
    registry.add('dialogue-join-by-talking', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_join_by_talking(ctx), doc="The host talks to its NPC with the client 2000 units off: the client stays out of it (no menu) and reads\n    her line on its screen (relayed with the engine's force flag, so at any distance). Coming up to her copy and\n    talking to it, the client joins: its menu opens on the copy, the host's conversation goes on.")
    registry.add('dialogue-host-in-background', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_host_in_background(ctx), doc="The client talks to its copy with the host 800 units off: the host's game runs the conversation in the\n    background (no menu, its player not turned, free to move) and shows her line on its HUD, while the client's\n    menu opens. The host walks off and the conversation waits for a pick; walking back and talking to her, the\n    host joins: its menu opens on the conversation under way. Then the\n    host leaves it (Tab ends it for both), the client talks again, and a pick in the host's background\n    conversation says her line: the follower line ends it for both.")
    registry.add('dialogue-pick-reaches-host', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_pick_reaches_host(ctx), doc="The client talks to its copy (the host's game runs it in the background, the host 800 units off) and picks\n    an option with its keys: the client's menu does not say it, the host's game does (her line on the host's NPC,\n    voiced on the client's copy), and both games follow it: a goodbye ends the conversation for both, any other\n    line leads both to the same next list.")
    registry.add('dialogue-npc-removed-mid-conversation', ['dialogue', 'spawn', 'v1'], lambda ctx: dialogue.scenario_dialogue_npc_removed_mid_conversation(ctx), doc="The client talks to its copy of the host's NPC, and the host's game removes the NPC mid-conversation (a quest\n    disabling it, the console's disable and markfordelete): the client's copy goes without crashing its game, its\n    menu closes and both games end the conversation.")
    registry.add('guest-arrival-leaves-host-in-place', ['join', 'restart', 'session', 'v1'], lambda ctx: join.scenario_guest_arrival_leaves_host_in_place(ctx), doc="The client's game starts again at the main menu and joins with the host's world, as a friend joining: the host's\n    player stays where it stands. When it moves, the failure says when (the host's frames, harness body_trace) and\n    what the host's game logged around then (its copy of the client spawning, where).")
    registry.add('dialogue-options-are-the-hosts', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_options_are_the_hosts(ctx), doc='Every menu shows the host\'s list, judged for the host\'s player: Brenuin offers "Here. Have a gold piece." only\n    to a player carrying gold, and the party\'s gold is one purse (party-purse.md). The party carries 10: the client\n    talks to him (the host\'s game in the background) and its menu lists the coin. The client picks it: the host\'s game\n    says Brenuin\'s answer, its script runs for the client (party-model.md, rule 2) and takes one coin from the party;\n    the chat on both games names who said it. With the purse empty, nobody\'s menu lists the coin.')
    registry.add('dialogue-line-judged-for-guest', ['dialogue', 'quests'], lambda ctx: dialogue.scenario_dialogue_line_judged_for_guest(ctx), doc="The host judges a line for the player it is for (JudgedFor, shared-dialogue.md): Lucan's claw topic asks\n    whether the player holds the golden claw, a condition run on PlayerRef. Judged for the client's character on the\n    host, it reads that character's bag (the client's, which its copy carries), not the host's player's: with the claw\n    in the client's bag only, the client no longer gets the line for a player without it and the host still does;\n    with it in the host's only, the other way round.")
    registry.add('copy-knows-learned-spell', ['dialogue', 'magic'], lambda ctx: dialogue.scenario_copy_knows_learned_spell(ctx), doc="A spell the client learns is known to its character on the host (PerkService carries the added spells with\n    the perks): a host condition judged for the client (a College line's HasSpell on the target) reads the client's.\n    It forgets it: the copy does too. The host's own player learns nothing.")
    registry.add('ability-stays-on-copy', ['magic', 'v1'], lambda ctx: dialogue.scenario_ability_stays_on_copy(ctx), doc="A permanent ability the client takes (the Steed Stone's) is its character's on the host: the copy has the spell\n    (a host condition's HasSpell) and the client's carry weight, the host's own player neither. Both stay after the\n    party changes cell (the copy's 3D unloads and loads) and after the client rejoins; removed, both go from the copy.")
    registry.add('dialogue-options-are-the-partys', ['dialogue', 'quests'], lambda ctx: dialogue.scenario_dialogue_options_are_the_partys(ctx), doc='Every menu shows the party\'s list, each player\'s own line for a topic (shared-dialogue.md, "Decided 2026-10-29"):\n    the client holds Lucan\'s golden claw, the host does not. The client talks to Lucan and the host joins by talking\n    to him: both menus list the same topics in the same order, the client\'s with the line for a player holding the\n    claw, the host\'s with his line for one without it. The client presses it: the host\'s game says the client\'s line,\n    its script runs for the client (rule 2), and the claw leaves the client\'s bag.')
    registry.add('dialogue-highlight-is-shared', ['dialogue'], lambda ctx: dialogue.scenario_dialogue_highlight_is_shared(ctx), doc='One highlight for the conversation (shared-dialogue.md, "Decided 2026-10-29"): the client talks to Lucan, the\n    host joins. The client presses S: the host\'s menu highlights the same option; the host presses W: the client\'s\n    follows back. The golden claw quest at its stage 60 gives Lucan several topics (without it he has one).')
    registry.add('dialogue-quest-option-from-host', ['dialogue', 'quests', 'spawn'], lambda ctx: dialogue.scenario_dialogue_quest_option_from_host(ctx), doc="A guest's menu lists what the host's quests offer, whatever its own quest state: the client's game stops\n    Brenuin's coin quest (its own copy of it; a guest runs no quests and keeps what the save had), so its engine would\n    offer no coin. The host's quest runs and its player carries gold: the client talks to Brenuin and its menu lists\n    the coin, the host's list. The quest is started again on the client afterwards.")
    registry.add('dialogue-pick-says-the-hosts-line', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_pick_says_the_hosts_line(ctx), doc='A topic with a different line per player is said with the host\'s: Hulda\'s "rent a room" is the room for 10\n    gold for a player with the gold, "cannot afford it" for one without. The party carries at least 10 (one purse,\n    party-purse.md): the client\'s menu shows the host\'s line, the client picks it, and the host\'s game says it: the\n    room. Its script runs for the client (party-model.md, rule 2): the client\'s character pays, once, from the party\'s\n    gold. The room is the party\'s. Then both menus show the host\'s next list.')
    registry.add('natives-reach-matches-ida', ['scripts'], lambda ctx: dialogue.scenario_natives_reach_matches_ida(ctx), doc="The plugin's reading of which global natives act on this game's player (Papyrus/NativeReach, rule 2's natives\n    on the player) matches IDA's over the game (scripts/re/papyrus_natives.py, docs/re/papyrus_natives.tsv): no\n    native moves to the guest's game, or stays on the host, that IDA reads otherwise. Natives IDA does not list\n    (SKSE's) are not compared.")
    registry.add('dialogue-picker-gets-speech-experience', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_picker_gets_speech_experience(ctx), doc='A persuade\'s Speech experience is the picker\'s: the host\'s game says every line and runs its script for the\n    player who picked it (party-model.md, rule 2), and the Game.AdvanceSkill in it runs on that player\'s game. The\n    client talks to Ungrien\'s copy, asks about the Black-Briars and persuades him (FavorDialogueScript.Persuade; the\n    host\'s list, judged for the host\'s Speech, set to 30): the client\'s Speech gains experience, the host\'s does\n    not. The persuade sizes it from Game.GetPlayer().GetAv("Speechcraft"), the client\'s character on the host, which\n    carries the client\'s Speech (45). Its Game.QueryStat asks the client\'s game, whose bribes and intimidations are\n    counted (the host\'s are not): the achievement it then gives goes to the client\'s game. Then the host persuades\n    another Ungrien itself (his topic is gone once he is persuaded): its own Speech gains it, the client\'s not.')
    registry.add('dialogue-picker-trains', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_picker_trains(ctx), doc="A trainer's menu opens on the game of whoever picked its line: the client talks to Amren's copy and picks\n    training. The host's game says the line and runs its script for the client (party-model.md, rule 2), whose\n    Game.ShowTrainingMenu runs on the client's game, with the copy, over its dialogue menu as in single player; the\n    host's game opens nothing. The client trains once: its One-handed goes up, the host's stays as it was, and the\n    party's gold (one purse, party-purse.md) goes down once, on every player (the menu pays from the inventory itself,\n    InventoryChanges::RemoveItem). Leaving the training menu, the client is back in the conversation, as in\n    single player.")
    registry.add('party-gold-is-one', ['inventory', 'objects'], lambda ctx: inventory.scenario_party_gold_is_one(ctx), doc="The party's gold is one purse (docs/design/party-purse.md): the host's player's gold, which every player and\n    every copy carries. The client takes 50 gold from a chest (Take All): every player carries it. The host's player\n    spends 30: every player has less. The host's game gives the client's character 25, as a quest reward its action\n    ran does (rule 2): every player carries it.")
    registry.add('dialogue-refused-start', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_refused_start(ctx), doc="A conversation the host's game cannot start is refused to the peer who asked: the client talks to the copy\n    of an NPC that is fighting, its menu does not open and its chat says why. Once the fight is over, the host\n    talks to that NPC itself: the client's menu stays closed (the refused ask is forgotten), and the client can\n    then join by talking to the copy as usual.")
    registry.add('dialogue-said-line-waits', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_said_line_waits(ctx), doc="A line with reset hours is not offered again until they pass, on every game: the client gives Brenuin a\n    coin (its line comes back after 4 hours), leaves, and talks to him again: its menu no longer lists the coin,\n    as the host's game, which said the line, does not.")
    registry.add('dialogue-ends-on-travel', ['dialogue', 'spawn', 'travel'], lambda ctx: dialogue.scenario_dialogue_ends_on_travel(ctx), doc="Walking off does not end a conversation (the host talks from anywhere), travel does: the client talks to\n    Lydia's copy (the host's game in the background) and the host takes the party to the inn. The host's\n    conversation ends and the client's menu closes. Back home, the next conversation runs as usual: the host\n    talks to a new Lydia, the client's HUD shows her line and the client joins by talking to her copy (its copy of\n    the first Lydia was deleted mid-conversation, which left its game unable to talk to anyone).")
    registry.add('dialogue-said-once-line', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_said_once_line(ctx), doc="A say-once line is not said again once said, on any game: the client asks Hulda about the College (one of\n    her two say-once lines), leaves and talks to her again: its menu, as the host's (joined by talking), offers\n    the topic with her other line, not the one said. Both lines are marked unsaid on both games before and\n    after (they stay said in a game otherwise).")
    registry.add('dialogue-question-answered-by-who-can', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_question_answered_by_who_can(ctx), doc='A question only another player can answer is that player\'s to answer (shared-dialogue.md, "Decided\n    2026-10-29"): Onmund\'s "Why aren\'t there many Nords at the College?" has one answer, for a player who is not a\n    Nord; the host is a Nord, the client a Breton for the scenario. The client asks it, the host joined by talking:\n    both menus list the client\'s answer, named for it. The host presses it: nothing is said, and only the host\'s chat\n    says "I\'m sorry <name>, you don\'t know how to say that." The client presses it: the host\'s game says the client\'s\n    line and the conversation goes on. His greetings, said once in a game, are marked unsaid before and after.')
    registry.add('dialogue-npc-removed', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_npc_removed(ctx), doc="The NPC goes away mid-conversation (the host's game deletes it): the client's menu on its copy closes, and\n    the client can talk to the next NPC (a copy deleted while its game talks to it left that game unable to start\n    another conversation).")
    registry.add('dialogue-npc-starts', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_npc_starts(ctx), doc="An NPC starts the conversation (a force greet; NPCs run their AI on the host's game, so it greets the host's\n    player): it greets the party, every game's menu opens on it (the clients' on their copies), with the host's\n    topics, without anyone talking to it. While the client's conversation with another NPC runs in the\n    background, a force greet waits: the host's game stays in the client's conversation.")
    registry.add('dialogue-several-questions-deep', ['dialogue', 'spawn'], lambda ctx: dialogue.scenario_dialogue_several_questions_deep(ctx), doc="A conversation three questions deep, picked by turns: Andurs greets with a question; the client answers,\n    the host (joined by talking) asks the follow-up, the client answers the last one. After each pick both\n    menus show the host's next list (topics, lines, texts), the line's choices only, and a peer's not before the NPC\n    has answered.")
    registry.add('teleport-keeps-copies', ['cells', 'movement', 'spawn'], lambda ctx: travel.scenario_teleport_keeps_copies(ctx), doc="The client teleports within the cell (moveto): its game keeps the copies it shows (the host's\n    character and NPC stay the same actors). A respawned copy loses its state and id.")
    registry.add('party-changes-cells', ['cells', 'spawn'], lambda ctx: travel.scenario_party_changes_cells(ctx), doc="The party goes to another cell and back together (the party tether): each arrival drops the\n    copies the old cell took, and the host sends what is there. In each cell both games show the\n    other player again, and the client shows the host's NPCs there.")
    registry.add('party-stacks-on-arrival', ['cells'], lambda ctx: travel.scenario_party_stacks_on_arrival(ctx), doc="The party arrives on one spot (a coc puts the host on the cell's marker, the tether the client where the\n    host arrived): both stand on it, passing through each other on both games, and both games\n    show the same view, though each player looked its own way before. The client walks off it (nothing\n    else happens) and then into the host, which stops it: its collision is back. And again after travelling home.")
    registry.add('party-uses-door', ['cells', 'objects', 'spawn'], lambda ctx: travel.scenario_party_uses_door(ctx), doc="The host walks out of the inn through its door and the client follows (the party tether); then the\n    client leads back in and the host follows. Each time both games end up showing the other player and the\n    same view (the follower faces the way the leader arrived), and outside the client shows the host's NPCs.")
    registry.add('party-quick-travel', ['cells', 'objects', 'spawn'], lambda ctx: travel.scenario_party_quick_travel(ctx), doc="The client walks out of the inn and straight back in while the host's game stalls (a hitch, a slow\n    load), so the host gets both travels at once: it ends up where the party went last (the inn), and the\n    party settles there instead of bouncing between the two (a follower's stop on the way must not lead).\n    Loads here take ~0.2 s, too short for the race without the stall.")
    registry.add('party-fast-travels', ['cells', 'spawn', 'world'], lambda ctx: travel.scenario_party_fast_travels(ctx), doc="The party fast travels from the river to Riverwood within one worldspace, twice: the host leads and\n    the client follows (the party tether), then the client leads and the host follows. The host's trip\n    passes time and the client keeps the host's time; each time both games end up showing the other\n    player in Riverwood. Fast travel here is the console's FastTravel: it queues the same move, with the\n    marker, as the map's.")
    registry.add('party-loads-overlap', ['cells', 'travel'], lambda ctx: travel.scenario_party_loads_overlap(ctx), doc='Both leaders announce the destination before loading, so followers queue without waiting for arrival.')
    registry.add('guest-quest-teleport', ['cells', 'travel'], lambda ctx: travel.scenario_guest_quest_teleport(ctx), doc="The quest MoveTo native on a guest's own body leads the party to its destination.")
    registry.add('party-travel-with-menu', ['cells', 'travel'], lambda ctx: travel.scenario_party_travel_with_menu(ctx), doc='A following player can be in the inventory menu when the leader travels.')
    registry.add('guest-rides-host-horse', ['movement', 'spawn'], lambda ctx: mounts.scenario_guest_rides_host_horse(ctx), doc=None)
    registry.add('host-rides-horse', ['movement', 'spawn'], lambda ctx: mounts.scenario_host_rides_horse(ctx), doc=None)
