    registry.add('mounted-guest-leaves', ['movement', 'session', 'spawn'], lambda ctx: mounts.scenario_mounted_guest_leaves(ctx), doc=None)
    registry.add('party-travel-mounted-guest', ['cells', 'movement', 'spawn', 'travel'], lambda ctx: mounts.scenario_party_travel_mounted_guest(ctx), doc=None)
    registry.add('party-travel-dead-guest', ['cells', 'death', 'spawn', 'travel'], lambda ctx: combat.scenario_party_travel_dead_guest(ctx), doc='A killed guest follows the living leader through a load and retains its death and spectator state.')
    registry.add('sneak-host-player', ['ai', 'movement'], lambda ctx: movement.scenario_sneak_host_player(ctx), doc="Host sneaks and stands up; the client's copy of the host must follow.")
    registry.add('furniture-host-player', ['movement'], lambda ctx: movement.scenario_furniture_host_player(ctx), doc="Host uses the cooking spit and leaves it; the client's copy must follow both ways.")
    registry.add('furniture-client-player', ['movement'], lambda ctx: movement.scenario_furniture_client_player(ctx), doc="Client uses the cooking spit and leaves it; the host's copy must follow both ways.")
    registry.add('sneak-client-player', ['ai', 'movement'], lambda ctx: movement.scenario_sneak_client_player(ctx), doc="Client sneaks and stands up; the host's copy of the client must follow.")
    registry.add('dive-host-player', ['ai', 'cells', 'dialogue', 'movement'], lambda ctx: travel.scenario_dive_host_player(ctx), doc="Host dives, stays under, surfaces; the client's copy of the host follows without its own decisions.")
    registry.add('copy-leaves-water-with-owner', ['cells', 'movement'], lambda ctx: travel.scenario_copy_leaves_water_with_owner(ctx), doc="The host swims in the river and then stands on its bank (put there, as a script's MoveTo would): its copy\n    on the client swims while it does and stops swimming with it, though a copy's own controller never gets the\n    support that ends a swim (Character::sub_37946, docs/progress.md).")
    registry.add('dive-client-player', ['ai', 'cells', 'dialogue', 'movement'], lambda ctx: travel.scenario_dive_client_player(ctx), doc="Client dives, stays under, surfaces; the host's copy of the client follows without its own decisions.")
    registry.add('cast-host-player', ['hands', 'magic'], lambda ctx: movement.scenario_cast_host_player(ctx), doc="Host casts Flames (held) and stops; the client's copy of the host must follow.")
    registry.add('cast-client-player', ['hands', 'magic'], lambda ctx: movement.scenario_cast_client_player(ctx), doc="Client casts Flames (held) and stops; the host's copy of the client must follow.")
    registry.add('quick-sheathe-host-player', ['hands', 'magic'], lambda ctx: movement.scenario_quick_sheathe_host_player(ctx), doc="Host raises and at once lowers a spell; the client's copy must end with the hands down.")
    registry.add('quick-sheathe-client-player', ['hands', 'magic'], lambda ctx: movement.scenario_quick_sheathe_client_player(ctx), doc="Client raises and at once lowers a spell; the host's copy must end with the hands down.")
    registry.add('hands-survive-reload-host-player', ['hands', 'reload', 'spawn'], lambda ctx: movement.scenario_hands_survive_reload_host_player(ctx), doc="Host's hands up/down across hot reloads; the client's respawned copy must match.")
    registry.add('hands-survive-reload-client-player', ['hands', 'reload', 'spawn'], lambda ctx: movement.scenario_hands_survive_reload_client_player(ctx), doc="Client's hands up/down across hot reloads; the host's respawned copy must match.")
    registry.add('health-host-player', ['values'], lambda ctx: movement.scenario_health_host_player(ctx), doc="Host player loses/regains health; the client's copy of the host must match.")
    registry.add('health-client-player', ['values'], lambda ctx: movement.scenario_health_client_player(ctx), doc="Client player loses/regains health; the host's copy of the client must match.")
    registry.add('health-host-npc', ['values'], lambda ctx: combat.scenario_health_host_npc(ctx), doc="Host's NPC loses/regains health; the client's copy must match.")
    registry.add('death-host-npc', ['spawn', 'values'], lambda ctx: combat.scenario_death_host_npc(ctx), doc='The host resurrects an NPC; its existing copy draws and swings on a running graph afterward.')
    registry.add('death-spectate-host', ['combat', 'death', 'input', 'values'], lambda ctx: combat.scenario_death_spectate_host(ctx), doc='The host is downed by an enemy, spectates and respawns beside the guest after ten clear seconds.')
    registry.add('death-spectate-guest', ['combat', 'death', 'input', 'values'], lambda ctx: combat.scenario_death_spectate_guest(ctx), doc='The guest is downed by an enemy, spectates and respawns beside the host after ten clear seconds.')
    registry.add('death-wipe-checkpoint', ['combat', 'death', 'join', 'save'], lambda ctx: combat.scenario_death_wipe_checkpoint(ctx), doc='Enemy blows down both players; both games load the previous host save and keep their saved characters.')
    registry.add('friendly-fire-guest-sword', ['combat', 'values'], lambda ctx: combat.scenario_friendly_fire_guest_sword(ctx), doc="The guest's sword on the host's player: the host's game applies it.")
    registry.add('friendly-fire-host-sword', ['combat', 'values'], lambda ctx: combat.scenario_friendly_fire_host_sword(ctx), doc="The host's sword on the guest's player: the guest's game applies it.")
    registry.add('friendly-fire-guest-firebolt', ['combat', 'magic', 'values'], lambda ctx: combat.scenario_friendly_fire_guest_firebolt(ctx), doc="The guest's Firebolt on the host's player: the host's game applies it.")
    registry.add('friendly-fire-host-firebolt', ['combat', 'magic', 'values'], lambda ctx: combat.scenario_friendly_fire_host_firebolt(ctx), doc="The host's Firebolt on the guest's player: the guest's game applies it.")
    registry.add('friendly-fire-kill', ['combat', 'death', 'values'], lambda ctx: combat.scenario_friendly_fire_kill(ctx), doc="The host's sword kills the guest: a real death on the guest's game (its copy dies with it), the guest spectates,\n    and both chats name the killer.")
    registry.add('fus-ro-dah-host-hits-guest', ['combat', 'magic', 'physics', 'v1'], lambda ctx: combat.scenario_fus_ro_dah_host_hits_guest(ctx), doc="The host's real three-word shout knocks the guest down on its own game and the host's copy.")
    registry.add('fus-ro-dah-guest-hits-host', ['combat', 'magic', 'physics', 'v1'], lambda ctx: combat.scenario_fus_ro_dah_guest_hits_host(ctx), doc="The guest's real three-word shout knocks the host down on its own game and the guest's copy.")
    registry.add('kill-move-kills-guest', ['combat', 'death', 'physics'], lambda ctx: combat.scenario_kill_move_kills_guest(ctx), doc="The host's kill move kills the guest: one pair on both games, a real death named in both chats, the guest's\n    ragdoll on its game and its copy's on the host's move as bodies do (no back and forth, no flickers), and the guest\n    stands on its feet after the respawn.")
    registry.add('spectator-watches-kill-move', ['camera', 'combat', 'death'], lambda ctx: combat.scenario_spectator_watches_kill_move(ctx), doc="The guest is dead and spectates the host while the host kills a wolf with a kill move: the guest's view stays\n    third person behind the host, with nothing between them, through the whole kill move.")
    registry.add('melee-client-hits-host-npc', ['combat', 'values'], lambda ctx: combat.scenario_melee_client_hits_host_npc(ctx), doc="Client hits the host's NPC with a sword: the host's real NPC loses health, the client's copy\n    shows the host's value and the client's HUD its health bar.")
    registry.add('firebolt-client-hits-host-npc', ['combat', 'magic', 'values'], lambda ctx: combat.scenario_firebolt_client_hits_host_npc(ctx), doc="Client's Firebolt hits the host's NPC: only the host applies it.")
    registry.add('flames-client-hits-host-npc', ['combat', 'magic', 'values'], lambda ctx: combat.scenario_flames_client_hits_host_npc(ctx), doc="Client's Flames stream hits the host's NPC: only the host applies it.")
    registry.add('client-angers-host-ally', ['combat', 'magic'], lambda ctx: combat.scenario_client_angers_host_ally(ctx), doc='Client keeps hitting an ally NPC of the host with Firebolts: after the friendly-hit tolerance\n    it fights the client.')
    registry.add('client-spell-kill-credit', ['combat', 'magic'], lambda ctx: combat.scenario_client_spell_kill_credit(ctx), doc="Client kills a host NPC with a spell: the host records the client's character as the killer.")
    registry.add('xp-stays-personal', ['combat'], lambda ctx: combat.scenario_xp_stays_personal(ctx), doc="The guest's actual melee hit raises its own One-Handed; the host gains no experience from it.")
    registry.add('client-melee-kill-credit', ['combat'], lambda ctx: combat.scenario_client_melee_kill_credit(ctx), doc="Client kills a host NPC with a sword: the host records the client's character as the killer.")
    registry.add('host-kill-move', ['animation', 'combat', 'values'], lambda ctx: combat.scenario_host_kill_move(ctx), doc="The host's player kills a wolf with a kill move: on the client the host's character and the wolf's\n    copy play it as one pair (the engine pairs them, laid out as on the host), a moment later and at the\n    same pace, and the wolf dies with its owner. Leaves an animation trace (timeline, side-by-side frames).")
    registry.add('client-kill-move', ['animation', 'combat', 'values'], lambda ctx: combat.scenario_client_kill_move(ctx), doc="The client's player kills the host's wolf with a kill move: on the host the client's character and the real\n    wolf play it as one pair, a moment later and at the same pace, and the host records the client's character as\n    the killer. The wolf's copy on the client dies with its owner. Leaves an animation trace.")
    registry.add('clock-slows-for-everyone', ['combat', 'world'], lambda ctx: world.scenario_clock_slows_for_everyone(ctx), doc="A game slowing its clock slows every game's (a kill cam, Slow Time, a bow zoom; here the console's\n    `sgtm`, the same engine call), and back to normal, every game is.")
    registry.add('burning-shows-on-copy', ['combat', 'magic'], lambda ctx: magic.scenario_burning_shows_on_copy(ctx), doc="Client's Flames set the host's NPC burning: the host's game applies the effect, and the\n    client's copy shows the same fire (its owner's active effects, played as visuals only). When\n    the burning ends there, it ends on the copy too.")
    registry.add('copy-made-later-shows-effects', ['magic', 'spawn'], lambda ctx: magic.scenario_copy_made_later_shows_effects(ctx), doc="The host's staged Vilkas casts Oakflesh on himself while the client is away. The client joins again: the\n    copy it makes then shows the visuals from its spawn, nothing having changed on the host since (the owner sends\n    its effects only when the engine starts or ends one). A dispel ends them on both.")
    registry.add('copy-flashes-one-shot-effects', ['magic', 'spawn'], lambda ctx: magic.scenario_copy_flashes_one_shot_effects(ctx), doc="An effect whose visuals play once (no FX Persist) flashes on the copy as on its owner: the host's staged\n    Vilkas takes Gift of Charity (a beggar's blessing, an hour long). Its shader shows on the host's Vilkas and on\n    the client's copy, then ends on both by itself while the blessing still runs (the owner sends the flash when its\n    engine starts it).")
    registry.add('copy-flashes-instant-effects', ['magic', 'spawn'], lambda ctx: magic.scenario_copy_flashes_instant_effects(ctx), doc="A shrine's instant FX Persist cure effect flashes on the existing copy, then fades on both games.")
    registry.add('door-opens-for-both', ['objects'], lambda ctx: magic.scenario_door_opens_for_both(ctx), doc="A player opens a door: the other game's door opens too (the bridge relays the activation and\n    the other game's copy of the player opens it there). Then the host closes it for both.")
    registry.add('chest-take-all', ['inventory', 'objects'], lambda ctx: inventory.scenario_chest_take_all(ctx), doc="Both players use Take All: items reach the acting player and its copy.\n    The other game keeps its menu closed and its own player's inventory unchanged.")
    registry.add('host-drop-reaches-guest', ['inventory', 'objects', 'physics'], lambda ctx: inventory.scenario_host_drop_reaches_guest(ctx), doc="Feature 6: the host's player drops an enchanted, tempered, renamed sword. The guest's world shows one sword\n    with all of it; the guest's player picks it up, and it is gone from both worlds, in the guest's player's inventory\n    (extra data and all) and on the host's copy of it.")
    registry.add('guest-drop-reaches-host', ['inventory', 'objects', 'physics'], lambda ctx: inventory.scenario_guest_drop_reaches_host(ctx), doc="Feature 6: the guest's player drops the heirloom. The host's world makes the one sword the party sees, with all\n    its extra data; the guest's own stays its twin (one sword, not two); the host's player picks it up and it is gone\n    from both worlds.")
    registry.add('guest-pickup-race', ['inventory', 'objects'], lambda ctx: inventory.scenario_guest_pickup_race(ctx), doc="Feature 6: the host's player drops the heirloom and both players reach for it at once. The host's game is the\n    first to decide: one player carries it, the other nothing, and it lies in neither world.")
    registry.add('chest-keeps-tempered-item', ['inventory', 'objects'], lambda ctx: inventory.scenario_chest_keeps_tempered_item(ctx), doc="Feature 6: a chest keeps its items' extra data. The host's player stores the heirloom in the small chest: the\n    guest's chest holds it as it is. The guest's player stores a second one: the host's chest holds both as they are.")
    registry.add('guest-brewed-potion-reaches-host', ['inventory', 'menus', 'objects', 'potions'], lambda ctx: inventory.scenario_guest_brewed_potion_reaches_host(ctx), doc="The guest brews a potion at QASmoke's alchemy lab through its menu. Each game makes its own form for it; the\n    session names it by its recipe. The host's copy of the guest carries it; the guest drops it, the host's world makes\n    it and its player picks it up; the host stores it in the small chest, and the guest's chest holds it too.")
    registry.add('guest-poison-coating-reaches-host', ['inventory', 'menus', 'objects', 'potions'], lambda ctx: inventory.scenario_guest_poison_coating_reaches_host(ctx), doc="The guest brews a poison at the alchemy lab and coats its iron sword with it (a poison equipped, as the inventory\n    menu's Use: the weapon's ExtraPoison). It stores the sword in the small chest: the host's chest holds the sword with\n    the same poison, the host's own form for its recipe, and as many uses.")
    registry.add('crafted-potion-kept-across-rejoin', ['inventory', 'join', 'menus', 'potions', 'save'], lambda ctx: inventory.scenario_crafted_potion_kept_across_rejoin(ctx), doc="A guest's brewed potions are kept in its record with their recipes (crafted-potions.md): the client brews one, and\n    the host's record of it holds the recipe. Its game starts again (a new process: no created forms, an empty recipe\n    book) at the main menu and joins with the host's world: its player carries the potion, made again from the\n    record's recipe, and the host's copy of it carries it too.")
    registry.add('guest-loads-propose-no-locks', ['cells', 'objects'], lambda ctx: inventory.scenario_guest_loads_propose_no_locks(ctx), doc="A guest's own world changes no lock on the host's: its cell loads and its world scripts record lock changes\n    (AddLockChange from scripts' OnLoad and the engine's cell jobs), which only a player's lockpick or key may\n    propose. The party goes to Riverwood and back: the host takes none of the guest's.")
    registry.add('load-door-not-replayed', ['cells', 'objects'], lambda ctx: magic.scenario_load_door_not_replayed(ctx), doc="In the inn, the client walks out through its door: the host's game gets the activation and\n    does not replay it (the door would take the client's copy, or anyone, out of the host's cell);\n    only the client's own game takes it through, and the host follows by the party tether.")
    registry.add('plate-counts-client', ['cells', 'objects', 'scripts'], lambda ctx: objects.scenario_plate_counts_client(ctx), doc='The client walks across a pressure plate whose unpatched vanilla script only reacts to the player:\n    on the host its character counts as the player (docs/design/party-model.md, "A client\'s actions on\n    the host", rule 1), so the host\'s plate goes down under it and comes up again behind it.')
    registry.add('sword-box-asks-client', ['cells', 'inventory', 'objects', 'scripts'], lambda ctx: objects.scenario_sword_box_asks_client(ctx), doc="The client puts Red Eagle's sword in the stone and takes it back. On the host the box's check\n    counts its character as the player (rule 1), and the script the box starts asks that character for\n    the sword and hands it back to it (rule 2, docs/design/party-model.md): the host's player, who has\n    none, opens the door all the same and never gets the sword. The client's own box runs nothing\n    (world-state sync step 5): its sword goes once and comes back once, its door opens from the host's, and\n    it sees the host's script swap the box and the sword in the stone (step 6, enabled state). The client carries\n    a staff worth more than its axe: when the script takes the sword from the host's copy, the engine picks a\n    weapon for the copy (an NPC losing an item), which a copy refuses: it keeps its owner's hands.")
    registry.add('statue-fires-at-client', ['cells', 'magic', 'scripts'], lambda ctx: objects.scenario_statue_fires_at_client(ctx), doc="The client walks into Soljund's boss trigger: on the host its character counts as the player\n    (rule 1), and the updates the trigger registers for run for it (rule 2), so the host's fire statue\n    shoots at the client's character, not at the host's player, who stands out of the way. Checked by the\n    host's own hits; the client's own trigger runs nothing (world-state sync step 5), and the host's hit\n    burns the client's player through its game. No god mode: it keeps the hit from landing at all.")
    registry.add('ring-turns-for-client', ['cells', 'objects', 'scripts'], lambda ctx: objects.scenario_ring_turns_for_client(ctx), doc="The client turns a ring of a claw door three times round. On the host the ring's check counts\n    its character as the player (rule 1, docs/design/party-model.md), so the host's ring turns with it.\n    The client runs no world script (it never ran the ring's: its script has no state); its ring turns as\n    the host's does, from the host's animations.")
    registry.add('late-join-gets-ring-pose', ['cells', 'scripts', 'session', 'world'], lambda ctx: objects.scenario_late_join_gets_ring_pose(ctx), doc="The host turns a claw door's ring while the client is away; the client rejoins at the door. Its ring was\n    never animated there, so only the cell's state (the ring's graph, kGraph) can show the host's turn.")
    registry.add('keyhole-asks-client', ['cells', 'inventory', 'objects', 'scripts'], lambda ctx: objects.scenario_keyhole_asks_client(ctx), doc="The client, holding the claw, puts it in a claw door whose rings are wrong. On the host the\n    keyhole counts its character as the player (rule 1) and asks it for the claw (rule 2): the host's\n    player has none, yet the keyhole takes the try (busy, then back) and the door stays shut.")
    registry.add('relief-takes-client-relics', ['cells', 'inventory', 'objects', 'scripts'], lambda ctx: story.scenario_relief_takes_client_relics(ctx), doc="The client, carrying Volunruud's ceremonial axe, puts it in the relief. On the host the door's script holds the\n    host's player (stored when its cell loaded) and asks that variable for the relics: in a stack run for the client,\n    the native sees the client's character in its place (party-model.md, rule 2: a stored player), so the axe is\n    taken from the client and the relief shows it on both games, though the host's player holds none; the box saying\n    the sword is still missing is the client's (its action's Message.Show runs on its game, party-calls.md), the host\n    shows none. The quest is set to stage 10 first\n    (a first activation sets it, with a box) and stays there: stages only go forward. The relief is emptied after.")
    registry.add('words-reach-party', ['dragonborn', 'objects', 'scripts'], lambda ctx: story.scenario_words_reach_party(ctx), doc="Forms as a native's arguments, and the party's words (docs/design/dragonborn.md): the client presses the QA\n    shout button. The host's game runs its script for the client (party-model.md, rule 2), and Game.TeachWord and\n    Game.UnlockWord act on this game's player (NativeReach), so the client's game runs them, each word carried by its\n    GameId. Each word its player learns, and each a script unlocks, is the party's: the host's player learns and\n    unlocks the twelve too.")
    registry.add('host-word-reaches-guest', ['dragonborn', 'scripts'], lambda ctx: story.scenario_host_word_reaches_guest(ctx), doc="The host's own script (a quest's, no player's action behind it) teaches its player a word and unlocks it: the\n    client's player learns it, through its engine's own Game.TeachWord (the word's HUD, the shout), and has it\n    unlocked; a word forgotten again stays forgotten on the other game (only learning is shared).")
    registry.add('dragon-soul-reaches-party', ['dragonborn', 'scripts', 'spawn'], lambda ctx: story.scenario_dragon_soul_reaches_party(ctx), doc='A dragon each player kills gives every player its soul (dragonborn.md, "A soul, traced"). The host spawns a\n    dragon on the stage and it dies by the killer\'s hand (Actor.Kill: OnDeath\'s killer is the host\'s player, then the\n    client\'s character on the host). Its script waits for the killer near (deadAndWaiting), then\n    MQKillDragonScript.DeathSequence absorbs the soul into Game.GetPlayer(): the killer (rule 2 for the client\'s\n    kill). Each game\'s player gains exactly one soul per dragon, through its engine\'s own value, and the client\'s\n    copy of the dragon dissolves as the host\'s does (its art: what a reference shows), and every game shows the\n    absorb\'s streams between the dragon and its own player (a death is the world\'s event).')
    registry.add('title-reaches-party', ['dragonborn', 'magic', 'scripts'], lambda ctx: story.scenario_title_reaches_party(ctx), doc="The story's titles and blood are the party's (dragonborn.md): a quest's script (no player's action behind it)\n    makes the client's character on the host Harbinger (C06's Game.GetPlayer().AddToFaction, run for the client) and\n    gives the host's player Beast Form (C03's rampage): both players are Harbinger and both can transform. The story\n    takes Beast Form back from both.")
    registry.add('vampirism-is-each-players', ['dragonborn', 'magic', 'scripts'], lambda ctx: story.scenario_vampirism_is_each_players(ctx), doc="Vampirism is each player's own (docs/design/system-quests.md): the client catches Sanguinare Vampiris (the\n    trap's, no catch roll); three days on (the host's clock run fast) its effect's script calls\n    PlayerVampireQuest.VampireChange, which makes the quest one per player on every game. The client turns, and the\n    host's copy of it; the host's player stays as it was; PlayerIsVampire is each game's own. Falion's cure (VC01's\n    stage 200, the story) runs on every game, each on its own player: the client is cured.")
    registry.add('vampirism-kept-across-rejoin', ['dragonborn', 'join', 'magic', 'save'], lambda ctx: story.scenario_vampirism_kept_across_rejoin(ctx), doc="A guest's vampirism is kept in its record (system-quests.md, rule 5): the client turns, and the host's record\n    of it keeps its own PlayerVampireQuest instance (its hunger's status and registration). Its game starts again at\n    the main menu and joins with the host's world, whose save holds the host's player's instance: its player is the\n    vampire it was, its instance its own again (VampireStatus 1, PlayerIsVampire 1, the host's 0).")
    registry.add('marriage-is-the-partys', ['dragonborn', 'scripts', 'spawn'], lambda ctx: story.scenario_marriage_is_the_partys(ctx), doc="A spouse is the party's (dragonborn.md): the wedding's fragment, run for the client\n    (QF_RelationshipMarriageWeddin's Alias_LoveInterest.SetRelationshipRank(Game.GetPlayer(), 4)), sets the NPC's\n    relationship with the client's character on the host; it is the player's (0x7), so the host's own conditions\n    (GetRelationshipRank with the player: the spouse's dialogue) read lover.")
    registry.add('host-beast-form-stays-host', ['dragonborn', 'magic', 'quests', 'scripts'], lambda ctx: magic.scenario_host_beast_form_stays_host(ctx), doc='The host turns into a werewolf with Beast Form (the Shout key). Its body\'s quest (PlayerWerewolfQuest, started by\n    the change effect on its player) adds it to the werewolf\'s factions as that quest\'s stage: a player\'s own moment,\n    not the story (dragonborn.md, "a quest a player\'s body started"), so the client\'s player stays out of them.')
    registry.add('cutscene-fade-reaches-party', ['scripts'], lambda ctx: story.scenario_cutscene_fade_reaches_party(ctx), doc="In the host's cutscene (controls taken) its script fades to black (ImageSpaceModifier.Apply on FadeToBlackImod)\n    and shakes the camera: the client's screen fades and shakes too, and clears with the host's; the controls come\n    back with the host's.")
    registry.add('guest-cutscene-reaches-host', ['scripts'], lambda ctx: story.scenario_guest_cutscene_reaches_host(ctx), doc="A script with no player's action behind it on the client's game takes its player's controls and fades to\n    black: the host's controls and screen follow, and come back with the client's. (Its player's own script would be\n    its moment alone: player-moment-stays-theirs.)")
    registry.add('screen-reaches-party', ['scripts'], lambda ctx: story.scenario_screen_reaches_party(ctx), doc="Outside a cutscene too, a script's shake and fade are the party's (a trap, a boss's music, a spell's look): the\n    host's script shakes the camera and fades, and the client's screen does too, and clears with the host's.")
    registry.add('story-message-reaches-party', ['scripts'], lambda ctx: story.scenario_story_message_reaches_party(ctx), doc="The host's messages go to everyone (party-model.md rule 5, party-calls.md): a quest's notification (no player's\n    action behind it) shows on every game. The client's own action's notification stays on the client: a quest's\n    notification on the client after it reaches the host, and the client's own never did.")
    registry.add('story-box-host-answers', ['scripts'], lambda ctx: story.scenario_story_box_host_answers(ctx), doc='A quest\'s message box with buttons (Message.Show, no player\'s action behind it) shows on every game; the host\'s\n    player answers it (Cancel), and the client\'s copy closes with the host\'s answer (party-calls.md, "A box\'s answer";\n    the user\'s choice, 2026-10-27: the host answers, the others see it).')
    registry.add('timer-asks-party-position', ['scripts'], lambda ctx: story.scenario_timer_asks_party_position(ctx), doc='Where the player is, asked with no player\'s action behind it (a quest\'s timer), is asked of the party (party-model.md\n    rule 3, party-calls.md "Questions"): Lydia stands with the client close and the host across the room; a quest asking\n    her distance to the player gets the client\'s, the nearer; the host\'s own action asking it gets the host\'s.')
    registry.add('player-moment-stays-theirs', ['scripts'], lambda ctx: story.scenario_player_moment_stays_theirs(ctx), doc='A script one player\'s action started (a lever, fishing, the lute) takes that player\'s controls and fades their\n    screen: that game\'s alone, the other\'s controls and screen stay as they are (PartyNatives; docs/design/cutscenes.md,\n    "Whose moment"). The host\'s player first, then the client\'s.')
    registry.add('player-stage-cutscene-reaches-party', ['quests', 'scripts'], lambda ctx: story.scenario_player_stage_cutscene_reaches_party(ctx), doc="A player's own script shaking the camera shakes that game only; a quest stage that player's script sets is the\n    story, and its fragment's screen calls reach the client too (MG04MonkSceneQuest stage 200: its loop pops to its\n    outro, ImageSpaceModifier.PopTo).")
    registry.add('elder-scroll-vision-reaches-party', ['late-save', 'quests', 'scripts', 'travel'], lambda ctx: story.scenario_elder_scroll_vision_reaches_party(ctx), doc="(duo --save LateAfterElderKnowledge) MQ206's stage sends Game.GetPlayer() into the Elder Scroll's vision\n    (moveTo its marker): the story's call on the player, so each game's own player goes there by its own MoveTo. The\n    client's mirrored move leads no one: the host's game gets no party travel from it.")
    registry.add('greybeards-scene-casts-party', ['ai', 'late-save', 'quests', 'scripts'], lambda ctx: story.scenario_greybeards_scene_casts_party(ctx), doc="(duo --save LateAfterDragonRising) MQ105's stage 270 starts an engine scene that casts the host's player (a\n    package on its alias): each guest's own player runs the same package (GuestScene) while the scene holds the host's\n    player, and is its own again when the scene lets it go.")
    registry.add('guest-script-stage-reaches-host', ['quests', 'scripts', 'world'], lambda ctx: story.scenario_guest_script_stage_reaches_host(ctx), doc="A script on the client's own game (an item's, as the Elder Scroll's MQ206.SetStage(20)) sets a quest's stage:\n    the host's game sets it, for the client (PlayerNatives::SendToHost), and runs its fragment; the client takes the\n    stage from the host, its fragment skipped.")
    registry.add('shrine-blesses-client', ['cells', 'magic', 'objects', 'scripts'], lambda ctx: story.scenario_shrine_blesses_client(ctx), doc="The host and the client each pray at a different temple shrine: each player gets only their own\n    shrine's blessing, though each game sees the other's character pray too (the host's script casts at\n    the client's character, which its owner's game applies; upstream's patch skipped other players).")
    registry.add('vilkas-counts-client-hits', ['combat', 'inventory', 'quests', 'scripts'], lambda ctx: story.scenario_vilkas_counts_client_hits(ctx), doc='The client spars with Vilkas for the Companions\' trial. On the host his trial script counts the\n    client\'s character as the player (rule 1): three hits pass the trial instead of ending it ("someone\n    else hit him"). Rule 1 only: nothing the hits start asks for the player.')
    registry.add('copy-runs-owners-package', ['ai', 'spawn'], lambda ctx: ai.scenario_copy_runs_owners_package(ctx), doc='The host\'s Vilkas runs one package, then another (staged: frozen, the package put in place as his evaluation\n    would). The client\'s copy runs the same one each time: its package field and the condition GetIsCurrentPackage,\n    which dialogue lines read on the speaker, answer as on the host, and its running slot, which plugins (Open\n    Animation Replacer) read inline, holds it (copy-contract.md, "AI state").')
    registry.add('copy-in-owners-combat', ['ai', 'combat'], lambda ctx: ai.scenario_copy_in_owners_combat(ctx), doc='The host\'s Vilkas (staged, his AI on: combat needs it) starts combat with the host\'s player, then stops. On the client his copy, which has no combat controller, answers IsInCombat and GetCombatState\n    as the host\'s Vilkas does (copy-contract.md, "AI state"). Its combat target is not checked: the engine clears the\n    field on a copy, which its own callers see out of combat (progress.md, overnight slice 3).')
    registry.add('guest-player-in-hosts-combat', ['ai', 'combat'], lambda ctx: ai.scenario_guest_player_in_hosts_combat(ctx), doc="The host's Vilkas (staged, his AI on) starts combat with the client's character, then stops. The client's\n    player counts as in combat while he fights it, as a player does from the combat groups targeting it (41238):\n    the host's NPCs are copies on the client, with no combat groups, so their AI state counts instead.")
    registry.add('guest-player-in-switched-combat', ['ai', 'combat'], lambda ctx: ai.scenario_guest_player_in_switched_combat(ctx), doc="The host's Vilkas (staged, his AI on) fights the host's player, then turns on the client's character without\n    leaving combat: both are his targets, and the host's player steps 1500 units away (the closer one wins). A switch\n    inside a fight sends no combat event (TESCombatEvent is a state change): the host's combat controller setting\n    its target (33235) says so. The client's player counts as in combat from then on.")
    registry.add('copy-holds-owners-factions', ['ai', 'spawn'], lambda ctx: ai.scenario_copy_holds_owners_factions(ctx), doc="The host's Vilkas is given a rank in a faction, another, and leaves it (the console's AddToFaction, SetFactionRank,\n    RemoveFromFaction). The client's copy answers GetFactionRank as he does each time: the owner sends its factions\n    when the engine writes them, with no periodic check.")
    registry.add('client-beast-form-stays-client', ['magic', 'quests', 'scripts', 'spawn'], lambda ctx: magic.scenario_client_beast_form_stays_client(ctx), doc="The client turns into a werewolf with Beast Form (the Shout key): its own character changes, the host\n    shows it changed, and the host's own player does not (upstream's bug: the change effect's\n    `Target == Game.GetPlayer()` passed for the client and the transformation went to the host's player).\n    The change effect's script runs on the client's game only (the target's owner applies effects), so the\n    host's PlayerWerewolfQuest stays stopped. Then the client changes back.")
    registry.add('chat-reaches-everyone', ['session', 'ui'], lambda ctx: interface.scenario_chat_reaches_everyone(ctx), doc='The client types a line (Enter, the text, Enter): both games show it under the client\'s name, and\n    the client\'s character did not walk while it typed ("w" is forward). The host answers. A line\n    abandoned with Escape reaches nobody.')
    registry.add('map-marker-reaches-everyone', ['ui', 'world'], lambda ctx: interface.scenario_map_marker_reaches_everyone(ctx), doc='Outdoors, the client places a marker on its map: the host\'s map shows it at the same spot. Then the\n    host places one: the client\'s moves there. The client removes it (P on it, "Remove It"): the host\'s\n    goes too. (Each placement starts without a marker: one already there turns P into that box.)')
    registry.add('host-time-reaches-client', ['world'], lambda ctx: world.scenario_host_time_reaches_client(ctx), doc="The host sets the hour: it stays set on the host (the host's clock is the session's) and the\n    client's clock follows.")
    registry.add('shared-wait-host', ['wait', 'world'], lambda ctx: world.scenario_shared_wait_host(ctx), doc='The host waits across midnight; both menus, calendars and native health recovery agree.')
    registry.add('shared-wait-guest', ['wait', 'world'], lambda ctx: world.scenario_shared_wait_guest(ctx), doc='The guest asks for a wait; the host drives both menus and calendars across midnight.')
    registry.add('shared-sleep-host', ['wait', 'world'], lambda ctx: world.scenario_shared_sleep_host(ctx), doc='The host sleeps in the inn; the guest waits, both calendars jump and the sleeper recovers health.')
    registry.add('shared-sleep-guest', ['wait', 'world'], lambda ctx: world.scenario_shared_sleep_guest(ctx), doc="The guest sleeps in the inn; the host represents the party's sleep and drives the countdown.")
    registry.add('guest-sleep-fires-host-script', ['quests', 'scripts', 'wait', 'world'], lambda ctx: world.scenario_guest_sleep_fires_host_script(ctx), doc="A guest wait grants no host rested bonus; a guest sleep runs the host's vanilla PlayerSleepQuest.")
    registry.add('shared-wait-cancel', ['wait', 'world'], lambda ctx: world.scenario_shared_wait_cancel(ctx), doc='The guest cancels a host wait; both native menus close before all the requested hours pass.')
    registry.add('host-wait-reaches-guest', ['world'], lambda ctx: world.scenario_host_wait_reaches_guest(ctx), doc="The host waits 3 hours across midnight in the Wait menu, as a player does: the client's calendar takes\n    the jump, days passed (GameDaysPassed and the whole days the engine counts on from) and the date.")
    registry.add('late-join-gets-calendar', ['session', 'world'], lambda ctx: world.scenario_late_join_gets_calendar(ctx), doc="The host waits a day: leaving, the client's own clock counts on from the host's days passed, not those of\n    the save it loaded. The host waits again while the client is away: it joins with the host's days passed and date.")
    registry.add('guest-sets-time', ['ui', 'world'], lambda ctx: world.scenario_guest_sets_time(ctx), doc="At 22:30 the client types `/settime 6 0` in the chat: the host's clock runs on to 06:00 the next day, as\n    a wait does, and both games show it, days passed and date included. The command is no chat line.")
    registry.add('bug-report-writes-every-game', ['reports', 'session', 'ui'], lambda ctx: world.scenario_bug_report_writes_every_game(ctx), doc="The client types `/bug duo check`: both games say where they wrote their part of one report, each part has\n    its note, log, messages and snapshot, the host's the name of its save, kept once in reports/saves; the host's\n    /export zips them.")
    registry.add('weather-follows-host', ['cells', 'world'], lambda ctx: world.scenario_weather_follows_host(ctx), doc="Both players outdoors; the host's weather changes: the client's game takes it (the host's\n    weather is the session's), and keeps it while its own weather system would move on.")
    registry.add('form-state-round-trips', ['objects', 'spawn', 'world'], lambda ctx: inventory.scenario_form_state_round_trips(ctx), doc="World-state sync step 3: a form's save data through our own buffers. The client's character base\n    and the host's copy of it save the same bytes (the appearance went through FormState on spawn, form ids\n    as network ids); a door's lock saved on the host, unlocked, and loaded back is locked again.")
    registry.add('world-changes-reach-guest', ['inventory', 'objects', 'world'], lambda ctx: physics.scenario_world_changes_reach_guest(ctx), doc="World-state sync's check: every kind of change to a reference the host can make, one at a time, each put\n    back after. Reports every kind the client's world does not follow, then what still differs in the whole\n    loaded world, rather than stopping at the first.")
    registry.add('physics-push-reaches-guest', ['objects', 'physics'], lambda ctx: physics.scenario_physics_push_reaches_guest(ctx), doc="Physics sync (docs/design/physics-sync.md): the host's player knocks clutter with a fireball. The client's\n    object it knocks hardest is held by the host's frames (keyframed, its own physics off), its 3D flies with the\n    host's and lies where the host's lies; everything the blast woke rests before the world is compared.")
    registry.add('guest-cast-moves-host', ['combat', 'objects', 'physics'], lambda ctx: physics.scenario_guest_cast_moves_host(ctx), doc='Physics sync\'s step 5 (docs/design/physics-sync.md, "A guest\'s own actions"): the client\'s player knocks clutter\n    with a fireball. Its copy\'s cast is replayed on the host, whose blast throws the host\'s clutter; the client\'s\n    follows the host\'s, held keyframed, and lies where the host\'s lies.')
    registry.add('guest-bump-moves-host', ['movement', 'objects', 'physics'], lambda ctx: physics.scenario_guest_bump_moves_host(ctx), doc='Physics sync\'s step 5 (docs/design/physics-sync.md, "A guest\'s own actions"): the client\'s player walks into a\n    ladle on the floor. Its character pushes the client\'s ladle, and the host pushes its own with the same impulse\n    (copies move by SetPosition and push nothing themselves); the client shows its own push until the host\'s ladle\n    rests, then lies where the host\'s lies.')
    registry.add('guest-throw-lands-on-host', ['objects', 'physics'], lambda ctx: physics.scenario_guest_throw_lands_on_host(ctx), doc='Physics sync\'s step 6 (docs/design/physics-sync.md, "A guest\'s own actions"): the client\'s player grabs a\n    ladle (Activate held past fZKeyDelay; it stays held after the release), carries it and drops it (Activate again).\n    While it holds it, the host\'s ladle follows the client\'s hold (keyframed); dropped, it falls on the host from\n    where the client let go, and the client\'s own fall shows until the host\'s ladle rests, then lies as the host\'s.')
    registry.add('ragdoll-lies-as-host', ['death', 'physics'], lambda ctx: physics.scenario_ragdoll_lies_as_host(ctx), doc="Physics sync's ragdolls (docs/design/physics-sync.md): the host's player kills a wolf with fireballs. Its copy\n    dies by the host's death action, then its ragdoll's bodies are the host's frames, and the body lies where the\n    host's lies, bone by bone.")
    registry.add('knockdown-lies-as-host', ['physics'], lambda ctx: physics.scenario_knockdown_lies_as_host(ctx), doc="The host's player knocks a living NPC down: the client's copy lies and gets up with it.")
    registry.add('guest-knockdown-lies-on-host', ['physics'], lambda ctx: physics.scenario_guest_knockdown_lies_on_host(ctx), doc="The client's player is knocked down in its game: the host's copy of it lies and gets up with it.")
    registry.add('knockdown-smoke', ['physics'], lambda ctx: physics.scenario_knockdown_smoke(ctx), doc='Lydia stands between the two players, both facing her (watch both games: `watch`, `watch --instance client`);\n    the host knocks her down and she gets up, three times. Her copy must not snap where she does not: a frame where\n    its skeleton jumps and comes back (RagdollTrace.snaps).')
    registry.add('knockdown-front-and-back', ['physics'], lambda ctx: physics.scenario_knockdown_front_and_back(ctx), doc='Push a living NPC from the front and behind; each whole fall and get-up follows its owner.')
    registry.add('late-join-gets-cell-state', ['objects', 'session', 'world'], lambda ctx: physics.scenario_late_join_gets_cell_state(ctx), doc="World sync's state at a cell load, for a game that missed changes: the host locks a door and disables a\n    static while the client is away. The client rejoins standing in the same cell (no load to ask with: it asks\n    for the cells it has loaded on joining), and its cell is the host's.")
    registry.add('guest-opens-hosts-roll', ['cells', 'inventory', 'objects', 'world'], lambda ctx: physics.scenario_guest_opens_hosts_roll(ctx), doc="A container's leveled entries are the host's roll (world sync step 2b): in the inn, the client opens the\n    container with the most leveled entries that a player can reach (the merchant's stock chest under the floor is\n    not) as its player would (an open is what rolls them), and it holds what the host's does, which the host's game\n    rolled when the client's inn loaded.")
    registry.add('placed-leveled-items-are-hosts', ['cells', 'objects', 'world'], lambda ctx: physics.scenario_placed_leveled_items_are_hosts(ctx), doc="A reference placed with a leveled base picks it when its cell first loads (Soljund's Sinkhole's clutter book:\n    `DummyBook` with XLIB `LItemBookClutter`, 124 books): the client's is the host's pick, its 3D the new base's.\n    Where it rests is step 5's (physics), not checked here.")
    registry.add('input-keyboard-draw', ['hands', 'input'], lambda ctx: input.scenario_input_keyboard_draw(ctx), doc="The host presses R to ready a sword, then again to sheathe it: the game reacts to the key,\n    and the client's copy of the host follows.")
    registry.add('input-mouse-cast', ['hands', 'input', 'magic'], lambda ctx: input.scenario_input_mouse_cast(ctx), doc="The client holds the mouse button with Flames ready, then lets go: the game casts while it is\n    held, and the host's copy of the client casts, then stops.")
    registry.add('save-does-not-update-frozen-world', ['save', 'v1'], lambda ctx: v1.save_does_not_update_frozen_world(ctx), doc='Saving drains a frozen VM: that drain must not run the full co-op world update.')
    registry.add('save-load-gate', ['gate', 'save', 'v1'], lambda ctx: v1.save_load_gate(ctx), doc="The reload-freeze gate (v1-playtest-todo.md): with a guest in and the follower it recruited, the host's game\n    saves and loads each way a player does (quicksave and quickload, a save loaded from the Load menu, the load door's\n    autosave, a named save loaded by name, a party wipe back to its checkpoint), and after each the party plays on\n    through a fight, checked every ~10 s, with the follower still following its guest.")
